UPDATE pets
name = #{name}, species = #{species}, breed = #{breed}, birth_date = #{birthDate}, gender = #{gender}, is_neutered = #{isNeutered}, has_allergy = #{hasAllergy}, image_url = #{imageUrl},
WHERE pet_id = #{petId}

