SELECT pa.pet_id , pa.allergy_type_id , pat.code , pat.category , pat.label , pat.requires_text , pa.other_text FROM pet_allergies pa JOIN pet_allergy_types pat ON pat.allergy_type_id = pa.allergy_type_id WHERE pa.pet_id IN
#{petId}
ORDER BY FIELD(pat.category, 'FOOD', 'ENVIRONMENT', 'OTHER'), pat.sort_order, pat.allergy_type_id
